head.b:skin:
/* ============================================================
   Online Education Guru — Blogger Theme
   GitHub Pages સાઈટને Blogger માં embed કરે છે.
   ============================================================ */
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:'Noto Sans Gujarati','Noto Sans Devanagari',system-ui,sans-serif;background:#f6f7fb;color:#17182b}
.oeg-topbar{background:linear-gradient(120deg,#4f46e5,#7c3aed 55%,#db2777);color:#fff;padding:14px 20px;display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.oeg-topbar .logo{font-weight:800;font-size:1.15rem}
.oeg-topbar nav{margin-left:auto;display:flex;gap:6px;flex-wrap:wrap}
.oeg-topbar nav a{color:#fff;text-decoration:none;font-weight:600;font-size:.9rem;padding:7px 12px;border-radius:9px;background:rgba(255,255,255,.14)}
.oeg-topbar nav a:hover{background:rgba(255,255,255,.28)}
.oeg-frame-wrap{max-width:1280px;margin:0 auto;padding:18px}
.oeg-frame{width:100%;height:82vh;min-height:560px;border:1px solid #e3e6f0;border-radius:18px;box-shadow:0 24px 60px rgba(23,24,43,.14);background:#fff}
.oeg-note{max-width:1280px;margin:0 auto 26px;padding:0 18px;color:#5b5f7a;font-size:.9rem;text-align:center}
.oeg-posts{max-width:900px;margin:0 auto 40px;padding:0 18px}
.oeg-posts h2{margin:26px 0 14px;font-size:1.3rem}
.oeg-post{background:#fff;border:1px solid #e3e6f0;border-radius:14px;padding:18px;margin-bottom:14px}
.oeg-post h3{margin-bottom:6px}
.oeg-post .meta{color:#5b5f7a;font-size:.82rem;margin-bottom:8px}
.oeg-footer{text-align:center;color:#5b5f7a;font-size:.85rem;padding:22px;border-top:1px solid #e3e6f0;background:#fff}
.oeg-seolinks{max-width:1000px;margin:0 auto 26px;padding:14px 18px;display:flex;flex-wrap:wrap;gap:8px;align-items:center;font-size:.86rem}
.oeg-seolinks span{width:100%;margin-top:6px}
.oeg-seolinks a{color:#4f46e5;text-decoration:none;background:#eef0f7;border-radius:999px;padding:5px 11px}
.oeg-seolinks a:hover{background:#e0e3f5}
@media(max-width:640px){.oeg-frame{height:78vh;min-height:480px}}
